"""TeX font metrics as code, one module per font (generated by `gen`).

    table(font) -> (ENC, CHARS) or None   font: lower-case TFM name, 'cmmi10'

No file is read and no program is run: a font outside FONTS gives
None and the caller decides (tfm falls back to the TeX installation).
"""
import functools
import importlib

# the fonts with TeX metrics that pdf2mmd2's corpus, its twins and the
# books met (the tfm cache of 2026-10-18)
FONTS = """
bbold10 bbold5 bbold7 cmb10 cmbsy10 cmbsy5 cmbsy6 cmbsy7 cmbsy8 cmbsy9
cmbx10 cmbx12 cmbx5 cmbx6 cmbx7 cmbx8 cmbx9 cmbxti10 cmcsc10 cmex10 cmex7
cmex8 cmex9 cmitt10 cmmi10 cmmi12 cmmi5 cmmi6 cmmi7 cmmi8 cmmi9 cmmib10
cmmib5 cmmib6 cmmib7 cmmib8 cmmib9 cmr10 cmr12 cmr17 cmr5 cmr6 cmr7 cmr8
cmr9 cmsl10 cmsl8 cmsl9 cmss10 cmss12 cmss17 cmss8 cmss9 cmssbx10 cmssi10
cmssi8 cmssi9 cmsy10 cmsy5 cmsy6 cmsy7 cmsy8 cmsy9 cmti10 cmti12 cmti7 cmti8
cmti9 cmtt10 cmtt12 cmtt8 cmtt9 csr10 csr8 cssl10 dsrom10 dsrom12 dsrom8
euex10 eufb10 eufm10 eufm5 eufm7 eurm10 eurm7 eusm10 eusm5 eusm7 lasy10
lasy7 lasy8 lasy9 lcmss8 lcmssb8 line10 linew10 manfnt msam10 msam5 msam7
msam9 msbm10 msbm5 msbm7 ntxexb ntxsyralt pxex pxmia pxsy pxsys rntxbmi
rntxmi rntxmi5 rntxmi7 rpxbmi rpxmi rsfs10 rsfs5 rsfs7 rtxb rtxbmi rtxmi
rtxmi5 rtxmi7 rtxr rtxsc stmary10 stmary7 stmary8 stmary9 t1xtt txbsys
txex-bar txex txexas txexs txmia txsy txsya txsyb txsyc txsys txtt wasy10
wasy9 wncyr10 xyatip10 xybsql10 xybtip10 xycirc10 xycmat10 xycmbt10 xydash10
xyeuat10 xyeubt10
""".split()


def module(font):
    return "f_" + font.replace("-", "_")


_KNOWN = frozenset(FONTS)


@functools.lru_cache(maxsize=None)
def table(font):
    if font not in _KNOWN:
        return None
    m = importlib.import_module(f"{__name__}.{module(font)}")
    return m.ENC, m.CHARS
